/**
 * v5-E: the immediate ack.
 *
 * The ack exists so a slow turn does not look like a dead bot. Three things are
 * asserted here, and the first is the one Jaime corrected:
 *
 *   1. The line is GENERATED BY THE MODEL, in parallel with the turn, from the
 *      sender's real words — there is no canned string anywhere. A model failure
 *      must therefore produce NO text at all, not a fallback "vale".
 *   2. The timer decides only WHETHER: a turn that finishes first discards the
 *      generated line, a slow one sends it.
 *   3. Every failure degrades to the reaction and never rejects into the turn.
 *
 * Driven through the real consumer (real ChannelInbox, real timers, a fake agent
 * binary and a stubbed sender) so the wiring is exercised, not just the helpers.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterAll, afterEach, beforeEach, describe, expect, test } from "bun:test";

import { ChannelInbox, type Inbound } from "../src/channels/inbox";
import { startChannelConsumer } from "../src/channels/consumer";
import { SendLedger, type EvoSender } from "../src/channels/evoSend";
import { AckLedger, cleanAckLine, generateAckLine, DEFAULT_ACK } from "../src/channels/ack";
import { makeFakeAgent } from "./helpers/fake-agent";

const SENDER = "242554100576489@lid";
const ACCOUNT = "mini-assistant";
const GROUP = "120363411180584976@g.us";
const SESSION = "wa-mini-assistant-8bfe4ead";

const envBackup = { ...process.env };
let dir: string;

afterAll(() => {
  process.env = envBackup;
  if (dir) rmSync(dir, { recursive: true, force: true });
});

describe("cleanAckLine", () => {
  test("strips the framing a small model wraps its answer in", () => {
    expect(cleanAckLine('"Busco trenes Valencia-Madrid"')).toBe("Busco trenes Valencia-Madrid");
    expect(cleanAckLine("Entendido, buscaré trenes.")).toBe("Entendido, buscaré trenes");
    expect(cleanAckLine("Ack: reviso los logs")).toBe("reviso los logs");
    expect(cleanAckLine("\n\nVoy con ello\notra cosa")).toBe("Voy con ello");
  });

  test("keeps the line inside its byte budget without a dangling word", () => {
    const long = "a".repeat(500);
    const line = cleanAckLine(long, 100);
    expect(Buffer.byteLength(line)).toBeLessThanOrEqual(100);
    expect(line).not.toMatch(/\s$/);
  });
});

interface Run {
  ackTexts: string[];
  reactions: string[];
  reply: string | undefined;
  ackRow: ReturnType<AckLedger["get"]>;
  agentCalls: number;
}

/**
 * One accepted message through the real consumer.
 *
 * `modelLine` is what the (stubbed) provider answers with; `turnMs` is how long
 * the fake agent takes; the ack settings come from `ack`.
 */
async function runTurn(args: { modelLine: string | null; turnMs: number; ack?: Partial<typeof DEFAULT_ACK> }): Promise<Run> {
  dir = mkdtempSync(join(tmpdir(), "channel-ack-"));
  const inbox = new ChannelInbox(join(dir, "channels.sqlite"));
  inbox.bind({ channel: "whatsapp", account: ACCOUNT, thread: GROUP, session: SESSION, project: "wa-assistant", allowedSenders: [SENDER], policy: "all", model: "" });
  const agent = makeFakeAgent(join(dir, "agent"), { holdMs: args.turnMs });

  const ackTexts: string[] = [];
  const reactions: string[] = [];
  let reply: string | undefined;
  const sender = {
    sendText: async ({ text }: { text: string }) => {
      // The FIRST text is the ack when the timer beat the turn; the reply is
      // whatever carries the agent's answer.
      if (!ackTexts.length && args.modelLine !== null && args.turnMs > 250) ackTexts.push(text);
      else reply = text;
      return { kind: "sent" as const, replyId: `r${ackTexts.length + (reply ? 1 : 0)}` };
    },
    sendReaction: async ({ reaction }: { reaction: string }) => {
      reactions.push(reaction);
      return { kind: "sent" as const };
    },
    recentOutgoing: async () => [],
    sendImage: async () => ({ kind: "sent" as const, replyId: "r-img" }),
    sendDocument: async () => ({ kind: "sent" as const, replyId: "r-doc" }),
  } as unknown as EvoSender;

  // The provider the ack calls: one connection, one model, answer on tap.
  const connections = join(dir, "providers.json");
  Bun.write(
    connections,
    JSON.stringify([
      {
        id: "test", name: "Test", route: "openai-compat", prefix: "test", baseUrl: "http://127.0.0.1:1/v1",
        keyEnv: "TEST_KEY", key: "k".repeat(40), models: ["tiny"], defaultModel: "tiny",
      },
    ]),
  );
  process.env.MINITUI_CONNECTIONS_PATH = connections;
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any, init: any) => {
    if (String(input).includes("/chat/completions")) {
      if (args.modelLine === null) return new Response('{"error":{"message":"model down"}}', { status: 500 });
      const body = JSON.parse(String(init?.body ?? "{}")) as { messages: Array<{ content: string }>; max_tokens: number };
      // The subject must reach the model, or the ack cannot be about anything.
      const asked = body.messages.map((m) => m.content).join(" ");
      if (!asked.includes("trenes")) throw new Error("the ack prompt lost the sender's message");
      if (body.max_tokens! > 200) throw new Error("the ack must stay a tiny completion");
      return new Response(JSON.stringify({ choices: [{ message: { content: args.modelLine } }] }), { status: 200 });
    }
    return originalFetch(input, init);
  }) as typeof fetch;

  process.env.MINITUI_MINI_BIN = agent.script;
  process.env.MINITUI_EMBEDDED_AGENT = "0";
  process.env.MINITUI_DB_PATH = join(dir, "sessions.sqlite");
  process.env.MINITUI_NO_TITLE = "1";

  const message: Inbound = { channel: "whatsapp", account: ACCOUNT, thread: GROUP, messageId: "ack-1", sender: SENDER, sentAt: Date.now(), text: "Buscame trenes de Valencia a Madrid para este fin de semana", attachments: [] };
  const ackLedger = new AckLedger(inbox.db);
  const consumer = startChannelConsumer({
    inbox,
    sender,
    ledger: new SendLedger(inbox.db),
    ackLedger,
    ackModel: "test/tiny",
    ackConfig: { ...DEFAULT_ACK, delayMs: 250, modelTimeoutMs: 1_000, ...(args.ack ?? {}) },
    consumer: "test-consumer",
    sessionsDbPath: join(dir, "sessions.sqlite"),
    cwd: dir,
    idleMs: 20,
    maxTurnAttempts: 1,
    log: () => {},
  });
  inbox.accept(message);
  const deadline = Date.now() + 20_000;
  while ((!reply || !ackLedger.get(1)) && Date.now() < deadline) await Bun.sleep(40);
  // Let the ack's own async tail settle before reading the ledger.
  await Bun.sleep(400);
  consumer.stop();
  await consumer.done;
  globalThis.fetch = originalFetch;

  return { ackTexts, reactions, reply, ackRow: ackLedger.get(1), agentCalls: agent.calls().length };
}

describe("generateAckLine", () => {
  const connectionsPath = join(tmpdir(), "ack-connections.json");
  const originalFetch = globalThis.fetch;
  afterEach(() => {
    globalThis.fetch = originalFetch;
    rmSync(connectionsPath, { force: true });
  });

  function stubProvider(): void {
    Bun.write(
      connectionsPath,
      JSON.stringify([
        { id: "t", name: "T", route: "openai-compat", prefix: "t", baseUrl: "http://127.0.0.1:1/v1", keyEnv: "T_KEY", key: "k".repeat(40), models: ["tiny"], defaultModel: "tiny" },
      ]),
    );
    process.env.MINITUI_CONNECTIONS_PATH = connectionsPath;
  }

  test("a reasoning model that rejects enable_thinking gets a REAL token budget on retry", async () => {
    stubProvider();
    const budgets: number[] = [];
    globalThis.fetch = (async (_input: any, init: any) => {
      const body = JSON.parse(String(init?.body ?? "{}")) as { max_tokens: number; enable_thinking?: boolean };
      budgets.push(body.max_tokens);
      // The gateway refuses the flag. (`false` is falsy: test for the KEY, not
      // for a truthy value — a stub written the obvious way never fires.)
      if ("enable_thinking" in body) return new Response('{"error":{"param":"enable_thinking","message":"unknown_parameter"}}', { status: 400 });
      // …and the reasoning model burns the budget and returns nothing.
      const reasoningRoom = body.max_tokens >= 200;
      return new Response(
        JSON.stringify({ choices: [{ finish_reason: reasoningRoom ? "stop" : "length", message: { content: reasoningRoom ? "Busco los trenes" : null, reasoning_content: reasoningRoom ? null : "pensando…" } }] }),
        { status: 200 },
      );
    }) as typeof fetch;

    const result = await generateAckLine({ subject: "Buscame trenes de Valencia a Madrid", model: "t/tiny", config: { maxTokens: 60, modelTimeoutMs: 5_000 } });
    // The fallback would be useless at the fast path's budget — that is the bug.
    expect(budgets).toEqual([60, 240]);
    expect(result.line).toBe("Busco los trenes");
    expect(result.model).toBe("t/tiny");
  });

  test("the fast path keeps the tiny budget when the model accepts the flag", async () => {
    stubProvider();
    const budgets: number[] = [];
    globalThis.fetch = (async (_input: any, init: any) => {
      const body = JSON.parse(String(init?.body ?? "{}")) as { max_tokens: number };
      budgets.push(body.max_tokens);
      return new Response(JSON.stringify({ choices: [{ message: { content: "Busco los trenes" } }] }), { status: 200 });
    }) as typeof fetch;
    const result = await generateAckLine({ subject: "Buscame trenes", model: "t/tiny", config: { maxTokens: 60 } });
    expect(budgets).toEqual([60]);
    expect(result.line).toBe("Busco los trenes");
  });

  test("an unresolvable model yields no line rather than a canned one", async () => {
    stubProvider();
    const result = await generateAckLine({ subject: "hola", model: "nope/none", config: { maxTokens: 60 } });
    expect(result.line).toBeNull();
    expect(result.reason).toBe("unresolved_model");
  });
});

describe("the immediate ack", () => {
  test("a slow turn gets the model's own line, generated from the sender's words", async () => {
    const run = await runTurn({ modelLine: "Busco los trenes de Valencia a Madrid", turnMs: 1_500 });
    // The reaction is the instant signal.
    expect(run.reactions).toEqual(["👀"]);
    // The line is the MODEL's text verbatim — not a constant from this repo.
    expect(run.ackTexts).toEqual(["Busco los trenes de Valencia a Madrid"]);
    expect(run.ackRow?.generated).toBe("Busco los trenes de Valencia a Madrid");
    expect(run.ackRow?.sent).toBe("Busco los trenes de Valencia a Madrid");
    expect(run.ackRow?.disposition).toBe("sent");
    expect(run.ackRow?.model).toBe("test/tiny");
    // And the real reply still arrives afterwards.
    expect(run.reply).toBeTruthy();
    expect(run.agentCalls).toBe(1);
  });

  test("a fast turn sends NO ack: the generated line is discarded", async () => {
    const run = await runTurn({ modelLine: "Busco los trenes de Valencia a Madrid", turnMs: 0 });
    expect(run.ackTexts).toEqual([]);
    expect(run.reply).toBeTruthy();
    expect(run.reactions).toEqual(["👀"]);
    // The line WAS written and deliberately dropped — that is the audit trail.
    expect(run.ackRow?.generated).toBe("Busco los trenes de Valencia a Madrid");
    expect(run.ackRow?.sent).toBeNull();
    expect(run.ackRow?.disposition).toBe("discarded");
  });

  test("a model failure degrades to the reaction alone — never a canned line", async () => {
    const run = await runTurn({ modelLine: null, turnMs: 1_500 });
    expect(run.reactions).toEqual(["👀"]);
    expect(run.ackTexts).toEqual([]);
    expect(run.ackRow?.generated).toBeNull();
    expect(run.ackRow?.disposition).toBe("no_line");
    // The turn is untouched by the model's failure.
    expect(run.reply).toBeTruthy();
    expect(run.agentCalls).toBe(1);
  });

  test("an empty reaction disables the emoji but keeps the model's line", async () => {
    const run = await runTurn({ modelLine: "Busco los trenes de Valencia a Madrid", turnMs: 1_500, ack: { reaction: "" } });
    expect(run.reactions).toEqual([]);
    expect(run.ackTexts).toEqual(["Busco los trenes de Valencia a Madrid"]);
    expect(run.ackRow?.reactionState).toBe("skipped");
  });
});